class Solution {
public:
    bool queryString(string s, int n) {
        for (int i = 1; i <= n; i++) {
            string b;
            for (int x = i; x; x >>= 1) b.push_back('0' + (x & 1));
            reverse(b.begin(), b.end());
            if (s.find(b) == string::npos) return false;
        }
        return true;
    }
};

