class Solution {
public:
    bool queryString(string s, int n) {
        int L = 0;
        while ((1LL << L) <= n) L++;
        unordered_set<int> seen;
        int m = s.size();
        for (int i = 0; i < m; i++) {
            long long x = 0;
            for (int j = i; j < min(i + L, m); j++) {
                x = x * 2 + (s[j] - '0');
                if (x > n) break;
                if (x) seen.insert((int)x);
            }
        }
        return (int)seen.size() == n;
    }
};

