class Solution {
    public boolean queryString(String s, int n) {
        int L = Integer.SIZE - Integer.numberOfLeadingZeros(n);
        Set<Integer> seen = new HashSet<>();
        int m = s.length();
        for (int i = 0; i < m; i++) {
            long x = 0;
            for (int j = i; j < Math.min(i + L, m); j++) {
                x = x * 2 + (s.charAt(j) - '0');
                if (x > n) break;
                if (x > 0) seen.add((int) x);
            }
        }
        return seen.size() == n;
    }
}

